    if ($("plan-reminder-note")) {
      $("plan-reminder-note").textContent = times.length ? `Drink reminders: ${times.join(", ")}. ${times.some((t) => isNightTime(t)) ? "Includes a night time you added." : "No night alerts unless you add them."} On-device only.` : "No reminder times set.";
    }
